-- Identity lifecycle (E04 / Day 6 — P3.x): onboarding, sync, offboarding, the
-- append-only audit trail (P2.7), the transactional event outbox + consumer
-- idempotency (Part 4) and the security-event history (Part 6).
-- Must run on PostgreSQL (compose) AND H2 in PostgreSQL mode (local/tests):
-- stick to the common SQL subset — UUIDs are generated by the application.

-- TERMINATED is added additively: ACTIVE/DISABLED keep their meaning, TERMINATED
-- is the offboarding terminal state (E04). H2 has no "drop constraint if exists"
-- portable form, so the check is replaced by name (created in V1).
alter table employee drop constraint ck_employee_status;
alter table employee add constraint ck_employee_status
    check (status in ('ACTIVE', 'DISABLED', 'TERMINATED'));

-- Provisioning bookkeeping on the aggregate: coarse identity state and the last
-- successful onboarding / sync instants (nullable until onboarding runs).
alter table employee add column provisioning_status varchar(20) not null default 'NOT_PROVISIONED';
alter table employee add column provisioned_at timestamp with time zone;
alter table employee add column last_sync_at   timestamp with time zone;
alter table employee add constraint ck_employee_provisioning_status
    check (provisioning_status in ('NOT_PROVISIONED', 'PROVISIONED', 'FAILED', 'DISABLED', 'LOCKED'));

-- Append-only audit trail (BR-06): rows are only ever inserted. On PostgreSQL
-- the schema grants deny UPDATE/DELETE to the service role; H2 (dev/tests)
-- relies on the code path never issuing them.
create table audit_log (
    id          uuid         primary key,
    actor       varchar(255) not null,
    action      varchar(100) not null,
    resource    varchar(255) not null,
    details     varchar(2000),
    occurred_at timestamp with time zone not null
);
create index ix_audit_log_resource on audit_log (resource);

-- Provisioning history: one row per identity action attempt (onboard, sync,
-- disable, reset, unlock, role-sync), success or failure. Append-only.
create table provisioning_record (
    id          uuid        primary key,
    employee_id uuid        not null,
    keycloak_id uuid,
    action      varchar(40) not null,
    status      varchar(20) not null,
    detail      varchar(2000),
    occurred_at timestamp with time zone not null,
    constraint ck_provisioning_status check (status in ('PROVISIONED', 'FAILED', 'SYNCED', 'DISABLED',
        'LOCKED', 'UNLOCKED', 'PASSWORD_RESET', 'ROLES_SYNCED', 'SESSIONS_REVOKED')),
    constraint fk_provisioning_employee foreign key (employee_id) references employee (id)
);
create index ix_provisioning_record_employee on provisioning_record (employee_id, occurred_at);

-- Transactional outbox (Part 4): the event is written in the SAME transaction as
-- the state change (at-least-once source of truth). A relay drains unpublished
-- rows to the broker; attempts/last_error drive the retry policy.
create table event_outbox (
    id             uuid         primary key,
    aggregate_id   uuid         not null,
    type           varchar(60)  not null,
    payload        varchar(4000) not null,
    correlation_id varchar(64)  not null,
    created_at     timestamp with time zone not null,
    published_at   timestamp with time zone,
    attempts       integer      not null,
    last_error     varchar(2000)
);
create index ix_event_outbox_unpublished on event_outbox (published_at, created_at);

-- Consumer idempotency (Part 4): an at-least-once consumer records the event id
-- it has applied, so a redelivery is a no-op.
create table processed_event (
    event_id     uuid         not null,
    consumer     varchar(100) not null,
    processed_at timestamp with time zone not null,
    constraint pk_processed_event primary key (event_id, consumer)
);

-- Security-event history (Part 6): admin-driven identity security actions
-- (disable, lock, unlock, password reset, session/refresh revocation). Keycloak
-- native auth events (login/logout ingestion, P3.6) remain a later slice.
create table security_event (
    id          uuid         primary key,
    keycloak_id uuid,
    username    varchar(255),
    type        varchar(30)  not null,
    actor       varchar(255) not null,
    detail      varchar(2000),
    occurred_at timestamp with time zone not null
);
create index ix_security_event_keycloak on security_event (keycloak_id, occurred_at);
